<?php require __DIR__.'/includes/bootstrap.php';$st=$pdo->query('SELECT p.*,MIN(d.date_depart) prochain_depart FROM packages p LEFT JOIN package_departures d ON d.package_id=p.id AND d.date_depart>=CURDATE() WHERE p.actif=1 GROUP BY p.id ORDER BY p.prix');$rows=$st->fetchAll();$title='Circuits & forfaits';require __DIR__.'/includes/header.php';?>
<section class="max-w-7xl mx-auto px-4 pb-12"><div class="page-heading"><p class="page-eyebrow">Expériences Voyalo · Cameroun</p><h1 class="page-title">Voyagez plus loin, découvrez autrement</h1><p class="page-subtitle">Des circuits préparés pour vous faire vivre les paysages, les saveurs et les cultures du Cameroun.</p></div><div class="flex flex-wrap gap-2 mt-3 mb-6"><span class="pill">Départs programmés</span><span class="pill">Prix par personne en FCFA</span><span class="pill">Réservation en ligne</span></div>
<div class="grid md:grid-cols-2 lg:grid-cols-3 gap-5"><?php foreach($rows as $p):?><article class="package-card"><img loading="lazy" src="<?=e($p['image_principale']?:'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?auto=format&fit=crop&w=900&q=80')?>" alt="<?=e($p['titre'])?>"><div class="package-card-body"><p class="page-eyebrow">Circuit Voyalo</p><h2 class="text-xl font-black mt-1"><?=e($p['titre'])?></h2><div class="package-info"><span>◷ <?=$p['duree_jours']?> jours</span><?php if($p['prochain_depart']):?><span>· Prochain départ : <?=date('d/m/Y',strtotime($p['prochain_depart']))?></span><?php else:?><span>· Dates à venir</span><?php endif;?></div><p class="mt-3 text-sm text-slate-600 leading-relaxed"><?=e($p['description'])?></p><?php if($p['itineraire']):?><details class="mt-3 text-sm"><summary class="cursor-pointer text-teal-800 font-bold">Voir l'itinéraire</summary><p class="mt-2 text-slate-600"><?=nl2br(e($p['itineraire']))?></p></details><?php endif;?><div class="flex justify-between items-end mt-4"><div><small class="text-slate-500">À partir de</small><p class="font-black text-xl"><?=money($p['prix'])?></p></div><span class="text-xs text-slate-500">/ personne</span></div><form method="get" action="/checkout.php"><input type="hidden" name="type" value="forfait"><input type="hidden" name="package_id" value="<?=$p['id']?>"><div class="flex-1"><label class="text-xs">Date de départ</label><select name="date" required><option value="">Choisir une date</option><?php $d=$pdo->prepare('SELECT id,date_depart FROM package_departures WHERE package_id=? AND date_depart>=CURDATE() ORDER BY date_depart');$d->execute([$p['id']]);foreach($d as $dep):?><option value="<?=$dep['id']?>"><?=date('d/m/Y',strtotime($dep['date_depart']))?></option><?php endforeach;?></select></div><div><label class="text-xs">Personnes</label><input type="number" name="nb" value="1" min="1"></div><button class="btn">Réserver</button></form></div></article><?php endforeach;?><?php if(!$rows):?><div class="empty-state md:col-span-2 lg:col-span-3"><strong class="text-slate-800">Les prochains circuits se préparent.</strong><p class="mt-2">Revenez bientôt pour découvrir les départs disponibles.</p></div><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
